namespace sv_a165aacccb7741ba93f4f9b1bc2bfd5f.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Fires OnChange so any subscribed component can re-render when new data arrives.
/// Scoped lifetime ensures each user circuit has its own independent instance.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }
    public string? CurrentWarehouseId { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning a random low-stock count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts polling every 10 seconds for the given warehouse.
    /// Multiple callers share the same polling loop; the first caller starts it.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;

        CurrentWarehouseId = warehouseId;

        if (_cts is not null)
            return; // already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(_cts.Token);
    }

    /// <summary>
    /// Decrements the subscriber count. Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);

        if (_subscriberCount == 0)
        {
            CancelPolling();
        }
    }

    /// <summary>
    /// Switches to a new warehouse and immediately fetches fresh data.
    /// </summary>
    public async Task ChangeWarehouseAsync(string warehouseId)
    {
        CurrentWarehouseId = warehouseId;
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start so subscribers get data right away.
        if (CurrentWarehouseId is not null)
        {
            CurrentAlertCount = await GetLowStockCountAsync(CurrentWarehouseId);
            OnChange?.Invoke();
        }

        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                if (CurrentWarehouseId is null)
                    continue;

                CurrentAlertCount = await GetLowStockCountAsync(CurrentWarehouseId);
                OnChange?.Invoke();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on disposal / stop.
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        CancelPolling();
    }
}

