@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="badge bg-danger rounded-pill ms-1"
      style="@(AlertService.CurrentAlertCount == 0 ? "display:none;" : "")">
    @AlertService.CurrentAlertCount
</span>

@code {
    private Action? _handler;

    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        if (Warehouse is not null &&
            Warehouse.WarehouseId != AlertService.CurrentWarehouseId)
        {
            await AlertService.ChangeWarehouseAsync(Warehouse.WarehouseId);
        }
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnChange -= _handler;
    }
}

