@using sv_a165aacccb7741ba93f4f9b1bc2bfd5f.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="display-6">@(Warehouse?.WarehouseName ?? "None")</p>
                <p class="text-muted">@(Warehouse?.WarehouseId)</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card @(_alertCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(_alertCount > 0 ? "text-danger" : "text-success")">
                    @_alertCount
                </p>
                <p class="text-muted">Items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-info">
                    <span class="spinner-grow spinner-grow-sm" role="status"></span>
                    Active
                </p>
                <p class="text-muted">Refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <h4>Recent Alert History</h4>
    <ul class="list-group">
        @foreach (var entry in _history)
        {
            <li class="list-group-item d-flex justify-content-between">
                <span>@entry.Warehouse — @entry.Count low-stock item(s)</span>
                <span class="text-muted">@entry.Time.ToString("HH:mm:ss")</span>
            </li>
        }
        @if (_history.Count == 0)
        {
            <li class="list-group-item text-muted">Waiting for first poll…</li>
        }
    </ul>
</div>

@code {
    private int _alertCount;
    private readonly List<AlertEntry> _history = [];
    private Action? _handler;

    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(() =>
        {
            _alertCount = AlertService.CurrentAlertCount;

            if (Warehouse is not null)
            {
                _history.Insert(0, new AlertEntry(
                    Warehouse.WarehouseName, _alertCount, DateTime.Now));

                if (_history.Count > 10)
                    _history.RemoveAt(_history.Count - 1);
            }

            StateHasChanged();
        });

        AlertService.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
        {
            // Start polling for whichever warehouse is selected.
            AlertService.StartPolling(Warehouse.WarehouseId);
        }

        _alertCount = AlertService.CurrentAlertCount;
    }

    public void Dispose()
    {
        AlertService.StopPolling();

        if (_handler is not null)
            AlertService.OnChange -= _handler;
    }

    private sealed record AlertEntry(string Warehouse, int Count, DateTime Time);
}

