@using sv_a165aacccb7741ba93f4f9b1bc2bfd5f.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@rendermode InteractiveServer

<div class="d-flex align-items-center gap-2">
    <label class="text-nowrap mb-0 fw-semibold">Warehouse:</label>
    <select class="form-select form-select-sm" style="width: auto;"
            value="@_selectedId" @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseInfo.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private string _selectedId = WarehouseInfo.AvailableWarehouses[0].Id;

    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
        {
            _selectedId = Warehouse.WarehouseId;
        }
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? WarehouseInfo.AvailableWarehouses[0].Id;

        var match = WarehouseInfo.AvailableWarehouses
            .FirstOrDefault(w => w.Id == _selectedId);

        var updated = new WarehouseInfo
        {
            WarehouseId = match.Id ?? _selectedId,
            WarehouseName = match.Name ?? _selectedId
        };

        await WarehouseSource.NotifyChangedAsync(updated);
    }
}

